package dev.aura.player;

import static org.junit.Assert.*;import org.junit.*;import android.content.*;import android.media.*;import android.os.*;import android.view.*;import android.net.Uri;import androidx.media3.common.*;import androidx.media3.exoplayer.*;import androidx.media3.session.MediaSession;import androidx.test.platform.app.InstrumentationRegistry;import java.io.*;import java.nio.*;import java.util.*;import java.util.concurrent.*;

@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public class PlaybackStabilityTest {
    private final android.app.Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();private final Context c=instrumentation.getTargetContext();private MainActivity activity;
    @Before public void start()throws Exception{AudioSettings.init(c);AudioSettings.put("mode","android");AudioSettings.put("perfect",false);AudioSettings.put("device",0);for(String key:List.of("eq","sox","limiter"))AudioSettings.put(key,false);for(String key:List.of("bits","rate","preamp","crossfeed","balance"))AudioSettings.put(key,0);activity=(MainActivity)instrumentation.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->PlaybackService.instance!=null,10000);Thread.sleep(600);}
    @After public void finish()throws Exception{main(()->{engine().stop();engine().clearMediaItems();AudioSettings.put("mode","android");AudioSettings.put("perfect",false);UsbVolume.settingsChanged();activity.finish();return null;});}
    @Test public void resourceBudgetRecognizesOldAndLowMemoryDevices(){assertTrue(PlaybackBudget.choose(28,256,false,2L<<30).constrained());assertTrue(PlaybackBudget.choose(36,128,false,12L<<30).constrained());assertTrue(PlaybackBudget.choose(36,256,true,8L<<30).constrained());var normal=PlaybackBudget.choose(36,512,false,12L<<30);assertFalse(normal.constrained());assertEquals(8*1024*1024,normal.audioBytes());assertEquals(1,PlaybackBudget.choose(28,256,false,2L<<30).scanThreads());}
    @Test public void unityPcmBypassesDspAndLiveEqStillStartsProcessing()throws Exception{PcmSink sink=new PcmSink(c);try{sink.configure(new Format.Builder().setSampleMimeType(MimeTypes.AUDIO_RAW).setChannelCount(2).setSampleRate(44100).setPcmEncoding(C.ENCODING_PCM_16BIT).build(),0,null);var dsp=PcmSink.class.getDeclaredField("dsp");dsp.setAccessible(true);assertNull(dsp.get(sink));ByteBuffer first=ByteBuffer.allocateDirect(1024);assertTrue(sink.handleBuffer(first,0,1));AudioSettings.put("eq",true);sink.handleBuffer(ByteBuffer.allocateDirect(1024),6000,1);assertNotNull(dsp.get(sink));}finally{sink.reset();AudioSettings.put("eq",false);}}
    @Test public void decodedFloatIsNotAdvertisedAsDirectPcm()throws Exception{PcmSink sink=new PcmSink(c);var floating=new Format.Builder().setSampleMimeType(MimeTypes.AUDIO_RAW).setChannelCount(2).setSampleRate(48000).setPcmEncoding(C.ENCODING_PCM_FLOAT).build();assertEquals(PcmSink.SINK_FORMAT_SUPPORTED_WITH_TRANSCODING,sink.getFormatSupport(floating));AudioSettings.put("perfect",true);AudioSettings.put("mode","usb");assertNotEquals(PcmSink.SINK_FORMAT_SUPPORTED_DIRECTLY,sink.getFormatSupport(floating));}
    @Test public void hardwareAndSessionKeysControlUsbVolumeWithoutChangingPhoneVolume()throws Exception{AudioManager manager=c.getSystemService(AudioManager.class);int original=manager.getStreamVolume(AudioManager.STREAM_MUSIC);UsbVolume.Access previous=UsbVolume.access;int saved=c.getSharedPreferences("playback",0).getInt("usbSoftwareVolume",100);FakeAccess access=new FakeAccess(false);try{UsbVolume.access=access;c.getSharedPreferences("playback",0).edit().putInt("usbSoftwareVolume",100).commit();main(()->{AudioSettings.put("mode","usb");UsbVolume.refresh(c);return null;});await(()->!UsbVolume.state.checking(),5000);android.media.session.MediaController platform=main(()->new android.media.session.MediaController(c,session().getPlatformToken()));await(()->platform.getPlaybackInfo().getPlaybackType()==android.media.session.MediaController.PlaybackInfo.PLAYBACK_TYPE_REMOTE,5000);platform.adjustVolume(AudioManager.ADJUST_LOWER,0);await(()->UsbVolume.state.level()==98,4000);main(()->{activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_VOLUME_DOWN));activity.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_VOLUME_DOWN));return null;});assertEquals(96,UsbVolume.state.level());assertTrue(UsbVolume.softwareGain<1);assertEquals(original,manager.getStreamVolume(AudioManager.STREAM_MUSIC));main(()->{AudioSettings.put("mode","android");UsbVolume.settingsChanged();return null;});await(()->platform.getPlaybackInfo().getPlaybackType()==android.media.session.MediaController.PlaybackInfo.PLAYBACK_TYPE_LOCAL,5000);assertEquals(1,UsbVolume.softwareGain,0);assertEquals(original,manager.getStreamVolume(AudioManager.STREAM_MUSIC));}finally{access.generation++;UsbVolume.access=previous;c.getSharedPreferences("playback",0).edit().putInt("usbSoftwareVolume",saved).commit();main(()->{AudioSettings.put("mode","android");UsbVolume.disconnected();return null;});}}
    @Test public void perfectUsbVolumeUsesFeatureUnitAndNeverSoftwareGain()throws Exception{UsbVolume.Access previous=UsbVolume.access;FakeAccess access=new FakeAccess(true);try{UsbVolume.access=access;main(()->{AudioSettings.put("mode","usb");AudioSettings.put("perfect",true);UsbVolume.refresh(c);return null;});await(()->UsbVolume.state.hardware()&&!UsbVolume.state.checking(),5000);main(()->{UsbVolume.set(50);return null;});await(()->UsbVolume.state.level()==50,5000);assertEquals(-30*256,access.current);assertTrue(access.writes>0);int before=access.writes;for(int i=0;i<8;i++){main(()->{UsbVolume.adjust(-2);return null;});Thread.sleep(20);}assertTrue("Held volume key must update before release",access.writes>before);await(()->access.current< -30*256,3000);assertEquals(1,UsbVolume.softwareGain,0);}finally{access.generation++;UsbVolume.access=previous;main(()->{AudioSettings.put("mode","android");AudioSettings.put("perfect",false);UsbVolume.disconnected();return null;});}}
    @Test public void usbAttachPausePreferenceAndHiResEnginePersist()throws Exception{var prefs=c.getSharedPreferences("playback",0);boolean saved=prefs.getBoolean("pauseUsbAttach",true);try{for(boolean pause:new boolean[]{true,false})main(()->{var routing=(UsbAutoRouting)field(PlaybackService.instance,"routing");prefs.edit().putBoolean("pauseUsbAttach",pause).commit();AudioSettings.put("mode","hires");AudioSettings.put("bits",24);AudioSettings.put("rate",96000);engine().play();routing.pauseForAttach();assertEquals(!pause,engine().getPlayWhenReady());assertEquals("hires",AudioSettings.current.mode());assertEquals(24,AudioSettings.current.bits());assertEquals(96000,AudioSettings.current.sampleRate());engine().pause();return null;});}finally{prefs.edit().putBoolean("pauseUsbAttach",saved).commit();}}
    @Test public void repeatedSeekPauseAndTrackChangesRemainStableWithHeapPressure()throws Exception{File tone=new File(c.getCacheDir(),"stable-tone.wav");try(InputStream in=instrumentation.getContext().getAssets().open("tone.wav");OutputStream out=new FileOutputStream(tone)){out.write(Io.read(in));}byte[][] pressure=new byte[8][];for(int i=0;i<pressure.length;i++){pressure[i]=new byte[1024*1024];pressure[i][0]=(byte)i;}main(()->{engine().setMediaItems(List.of(MediaItem.fromUri(Uri.fromFile(tone)),MediaItem.fromUri(Uri.fromFile(tone))));engine().setRepeatMode(Player.REPEAT_MODE_ALL);engine().prepare();engine().play();return null;});await(()->main(()->engine().getCurrentPosition()>250),8000);for(int i=0;i<24;i++){final int turn=i;main(()->{assertNull(engine().getPlayerError());if(turn%3==0)engine().seekTo(turn%2,0);else engine().seekTo(500);if(turn%4==0){engine().pause();engine().play();}return null;});if(i==12)main(()->{activity.moveTaskToBack(true);return null;});Thread.sleep(700);}main(()->{assertNull(engine().getPlayerError());assertTrue(engine().isPlaying());return null;});org.json.JSONObject metrics=new org.json.JSONObject().put("heapLimitBytes",Runtime.getRuntime().maxMemory()).put("nativeHeapBytes",Debug.getNativeHeapAllocatedSize()).put("audioBudgetBytes",PlaybackBudget.get(c).audioBytes()).put("pressureBytes",8*1024*1024).put("transitions",24).put("backgroundPlayback",true);java.nio.file.Files.write(new File(c.getExternalFilesDir(null),"stability-0110.json").toPath(),metrics.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));System.out.println("Stability heap max="+Runtime.getRuntime().maxMemory()+" budget="+PlaybackBudget.get(c).audioBytes()+" retained pressure="+pressure.length+" MiB");int kept=0;for(byte[] bytes:pressure)kept+=bytes.length+(bytes[0]&255);assertEquals(8*1024*1024+28,kept);}
    private ExoPlayer engine()throws Exception{return (ExoPlayer)field(PlaybackService.instance,"player");}private MediaSession session()throws Exception{return (MediaSession)field(PlaybackService.instance,"session");}private Object field(Object object,String name)throws Exception{var field=object.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(object);}
    private <T>T main(Callable<T> task)throws Exception{FutureTask<T> future=new FutureTask<>(task);instrumentation.runOnMainSync(future);return future.get(20,TimeUnit.SECONDS);}private void await(Callable<Boolean> condition,long timeout)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(!condition.call()&&SystemClock.elapsedRealtime()<end)Thread.sleep(30);assertTrue(condition.call());}
    private static final class FakeAccess implements UsbVolume.Access {long generation=111;final boolean hardware;volatile int current=-20*256,writes;FakeAccess(boolean hardware){this.hardware=hardware;}public long generation(){return generation;}public boolean connected(){return true;}public byte[] descriptors(long expected){return hardware?new byte[]{9,4,0,0,0,1,1,0,0,10,36,6,2,1,1,2,0,0,0,9,4,1,1,1,1,2,0,0,7,36,1,1,1,1,0,7,5,1,1,(byte)192,0,1}:new byte[0];}public void claim(long expected,int iface){}public int control(long expected,int type,int request,int value,int index,byte[] bytes)throws IOException{if(expected!=generation)throw new IOException();if(type==0x21){current=UsbVolumeProtocol.signed(bytes,0);writes++;return 2;}int v=request==0x82?-60*256:request==0x83?0:request==0x84?256:current;bytes[0]=(byte)v;bytes[1]=(byte)(v>>8);return 2;}}
}
